-- Old scores deliberately retain NULL delivery tags: fetching is not verification.
ALTER TABLE aeo_scores ADD COLUMN delivered_ruleset_version INTEGER;
ALTER TABLE aeo_scores ADD COLUMN score_model_version TEXT;
CREATE TABLE aeo_delivery_expectations (
 site_id TEXT NOT NULL, ruleset_version INTEGER NOT NULL, payload_json TEXT NOT NULL,
 fetched_at TEXT NOT NULL, PRIMARY KEY(site_id,ruleset_version)
);
CREATE TABLE aeo_site_delivery (
 site_id TEXT PRIMARY KEY, delivered_version INTEGER NOT NULL, verified_at TEXT NOT NULL
);
CREATE TABLE aeo_autofix_jobs (
 site_id TEXT PRIMARY KEY, ruleset_version INTEGER NOT NULL, requested_at TEXT NOT NULL,
 actions_json TEXT NOT NULL, missing_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending'
);
CREATE TABLE aeo_learning_observations (
 run_id TEXT PRIMARY KEY, site_id TEXT NOT NULL, measured_at TEXT NOT NULL,
 score_scanned_at TEXT, scoring_ruleset_version INTEGER, delivered_ruleset_version INTEGER,
 model_version TEXT, measurement_json TEXT NOT NULL
);
CREATE INDEX idx_aeo_observations_site ON aeo_learning_observations(site_id,measured_at);

CREATE TABLE aeo_harvested_facts (
 site_id TEXT PRIMARY KEY,same_as_json TEXT NOT NULL,observed_at TEXT NOT NULL,source_url TEXT NOT NULL
);

-- Snapshot existing runtime defaults into a NEW version. Historical definitions
-- are immutable. Preserve the effective legacy LocalBusiness field list, rather
-- than silently replacing it with another industry's criteria.
INSERT INTO aeo_rulesets(version,created_at,definition_json,active,notes)
SELECT (SELECT COALESCE(MAX(version),0)+1 FROM aeo_rulesets),strftime('%Y-%m-%dT%H:%M:%fZ','now'),
 json_set(definition_json,'$.scoring',json('{"modelVersion":"u1-v4","weights":{"schema":30,"coverage":25,"legibility":20,"llms":15,"consistency":10},"statusFactors":{"OK":1,"WARN":0.5,"BAD":0},"invalidSchemaFactor":0.5,"schemaOk":0.8,"coverageOk":0.8,"coverageWarn":0.4,"coverageMix":[0.6,0.4],"legibilityMix":[0.6,0.2,0.2],"legibilityOk":0.75,"legibilityWarn":0.4,"llmsOk":0.7,"gateCap":15,"greenAt":80,"yellowAt":50,"aiCrawlers":["GPTBot","OAI-SearchBot","ChatGPT-User","ClaudeBot","Claude-Web","PerplexityBot","Google-Extended","Applebot-Extended"],"factTextPatterns":["(住所|所在地|address|〒\\s*\\d{3})","(?:tel|電話|phone)[\\s:：]*[+()\\d-]{7,}","(営業時間|opening hours|月曜|monday)","(?:latitude|longitude|緯度|経度)","https?:\\/\\/|公式サイト|website"],"minVisible":100,"minFactText":20,"minLlms":120,"usefulTypes":["organization","localbusiness","product","service","softwareapplication","article","newsarticle","blogposting","faqpage","website","restaurant","cafeorcoffeeshop","bakery","barorpub","fastfoodrestaurant","icecreamshop","winery","brewery","distillery","store","clothingstore","grocerystore","pharmacy","petstore","furniturestore","shoppingcenter","bookstore","florist","hardwarestore","jewelrystore","liquorstore","mobilephonestore","officeequipmentstore","shoestore","sportinggoodsstore","toystore","conveniencestore","departmentstore","electronicsstore","homegoodsstore","healthandbeautybusiness","hairsalon","beautysalon","dayspa","nailsalon","medicalbusiness","dentist","physician","hospital","veterinarycare","optician","healthclub","tattooparlor","lodgingbusiness","hotel","motel","hostel","bedandbreakfast","resort","campground","travelagency","touristinformationcenter","professionalservice","legalservice","accountingservice","financialservice","insuranceagency","realestateagent","notary","employmentagency","homeandconstructionbusiness","plumber","electrician","generalcontractor","roofingcontractor","movingcompany","housepainter","locksmith","autorepair","automotivebusiness","autodealer","autobodyshop","autopartsstore","autorental","autowash","gasstation","motorcycledealer","sportsactivitylocation","exercisegym","golfcourse","skiresort","swimmingpool","tenniscomplex","bowlingalley","entertainmentbusiness","movietheater","nightclub","casino","amusementpark","childcare","educationalorganization","school","preschool","library","museum","touristattraction","selfstorage","drycleaningorlaundry","emergencyservice","governmentoffice","internetcafe","recyclingcenter"]}'),'$.generation',json('{"entityTemplates":{"WebSite":{"@type":{"source":"@type"},"@id":{"source":"@id"},"url":{"source":"url"},"name":{"source":"name"},"description":{"source":"description"},"publisher":{"source":"publisher"}},"WebPage":{"@type":{"source":"@type"},"@id":{"source":"@id"},"url":{"source":"url"},"name":{"source":"name"},"headline":{"source":"headline"},"description":{"source":"description"},"datePublished":{"source":"datePublished"},"dateModified":{"source":"dateModified"},"inLanguage":{"source":"inLanguage"},"isPartOf":{"source":"isPartOf"},"publisher":{"source":"publisher"},"mainEntityOfPage":{"source":"mainEntityOfPage"},"image":{"source":"image"}},"BlogPosting":{"@type":{"source":"@type"},"@id":{"source":"@id"},"url":{"source":"url"},"name":{"source":"name"},"headline":{"source":"headline"},"description":{"source":"description"},"datePublished":{"source":"datePublished"},"dateModified":{"source":"dateModified"},"inLanguage":{"source":"inLanguage"},"isPartOf":{"source":"isPartOf"},"publisher":{"source":"publisher"},"mainEntityOfPage":{"source":"mainEntityOfPage"},"image":{"source":"image"},"author":{"source":"author"}},"FAQPage":{"@type":{"source":"@type"},"@id":{"source":"@id"},"mainEntity":{"source":"mainEntity"}},"Service":{"@type":{"source":"@type"},"@id":{"source":"@id"},"name":{"source":"name"},"provider":{"source":"provider"},"category":{"source":"category"},"additionalProperty":{"source":"additionalProperty"},"offers":{"source":"offers"},"potentialAction":{"source":"potentialAction"}}},"llmsSections":{"identity":[{"source":"name","template":"# {value}"},{"source":"description","template":"> {value}"}],"store_information":[{"literal":"## 店舗情報"},{"source":"address","template":"- 住所: {value}"},{"source":"tel","template":"- 電話: {value}"},{"source":"hours","template":"- 営業時間: {value}"},{"source":"reserve_url","template":"- 予約: {value}"},{"source":"url","template":"- サイト: {value}"}],"supported_ai_crawlers":[{"literal":"## 対応AIクローラー"},{"source":"crawlerNames","template":"{value}"}]},"properties":{"@context":{"source":"schemaContext","always":true},"@type":{"source":"schemaType","always":true},"name":{"source":"name","always":true},"url":{"source":"canonicalUrl"},"additionalType":{"source":"typeLabel"},"address":{"object":{"@type":{"literal":"PostalAddress"},"streetAddress":{"source":"address"}},"requires":["address"]},"telephone":{"source":"tel"},"openingHours":{"source":"hours"},"openingHoursSpecification":{"source":"structuredHours"},"geo":{"object":{"@type":{"literal":"GeoCoordinates"},"latitude":{"source":"lat"},"longitude":{"source":"lng"}},"requires":["lat","lng"]},"priceRange":{"source":"mappedPrice"},"image":{"source":"image"},"logo":{"source":"logo"},"potentialAction":{"object":{"@type":{"literal":"ReserveAction"},"target":{"source":"reserve_url"}},"requires":["reserve_url"]},"description":{"source":"description","optIn":true},"email":{"source":"email","optIn":true},"sameAs":{"source":"same_as","optIn":true}}}'),
 '$.schema.entityFields',COALESCE(json_extract(definition_json,'$.schema.entityFields'),
   json_set(json('{"LocalBusiness":{"name":true,"address":true,"telephone":true,"openingHoursSpecification":true,"geo":true,"priceRange":true,"url":true,"sameAs":true},"SoftwareApplication":{"name":true,"applicationCategory":true,"operatingSystem":true,"offers.price":true,"offers.priceCurrency":true,"description":true},"Product":{"name":true,"image":true,"description":true,"brand":true,"sku":true,"offers.price":true,"offers.priceCurrency":true,"offers.availability":true,"aggregateRating":true},"Service":{"name":true,"description":true,"provider":true,"areaServed":true,"serviceType":true,"offers.price":true},"Article":{"headline":true,"author":true,"datePublished":true,"dateModified":true,"image":true,"publisher":true},"WebSite":{"name":true,"url":true},"FAQPage":{"mainEntity":true},"Organization":{"sameAs":true}}'),'$.LocalBusiness',
     CASE WHEN json_array_length(json_extract(definition_json,'$.schema.scoredProps'))>0 THEN
       (SELECT json_group_object(CASE WHEN value='openinghours' THEN 'openingHours' ELSE value END,json('true'))
        FROM json_each(json_extract(definition_json,'$.schema.scoredProps'))
        WHERE value='name' OR COALESCE(json_extract(definition_json,'$.schema.fields.' || value),1)<>0)
     WHEN json_type(definition_json,'$.schema.fields')='object' THEN
       json_patch(json('{"name":true}'),json_extract(definition_json,'$.schema.fields'))
     ELSE json_extract(json('{"LocalBusiness":{"name":true,"address":true,"telephone":true,"openingHoursSpecification":true,"geo":true,"priceRange":true,"url":true,"sameAs":true},"SoftwareApplication":{"name":true,"applicationCategory":true,"operatingSystem":true,"offers.price":true,"offers.priceCurrency":true,"description":true},"Product":{"name":true,"image":true,"description":true,"brand":true,"sku":true,"offers.price":true,"offers.priceCurrency":true,"offers.availability":true,"aggregateRating":true},"Service":{"name":true,"description":true,"provider":true,"areaServed":true,"serviceType":true,"offers.price":true},"Article":{"headline":true,"author":true,"datePublished":true,"dateModified":true,"image":true,"publisher":true},"WebSite":{"name":true,"url":true},"FAQPage":{"mainEntity":true},"Organization":{"sameAs":true}}'),'$.LocalBusiness') END))),
 0,'migration:0032 centralized runtime defaults'
FROM aeo_rulesets WHERE active=1 ORDER BY version DESC LIMIT 1;
UPDATE aeo_rulesets SET active=0 WHERE active=1;
UPDATE aeo_rulesets SET active=1 WHERE notes='migration:0032 centralized runtime defaults';
INSERT INTO aeo_ruleset_activations(id,ruleset_version,activated_at,activated_by,notes)
SELECT 'act_0032',version,created_at,'migration:0032',notes FROM aeo_rulesets WHERE active=1;
